<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Applicant_Accounts{
 public static function init():void{add_action('rest_api_init',[self::class,'routes']);}
 public static function routes():void{register_rest_route('nvconsult/v1','/applicant/register',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[self::class,'register'],'permission_callback'=>'__return_true']);register_rest_route('nvconsult/v1','/applicant/claim',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[self::class,'claim'],'permission_callback'=>static fn()=>is_user_logged_in()]);}
 public static function register(WP_REST_Request$r){if(!get_option('users_can_register'))return new WP_Error('registration_disabled',__('Account registration is currently disabled.','nvconsult-core'),['status'=>403]);$email=sanitize_email((string)$r['email']);$name=sanitize_text_field((string)$r['name']);$password=(string)$r['password'];if(!is_email($email)||mb_strlen($name)<2)return new WP_Error('invalid_details',__('Enter a valid name and email.','nvconsult-core'),['status'=>400]);if(strlen($password)<10)return new WP_Error('weak_password',__('Password must contain at least 10 characters.','nvconsult-core'),['status'=>400]);if(email_exists($email))return new WP_Error('email_exists',__('An account already exists for this email. Please sign in.','nvconsult-core'),['status'=>409]);$base=sanitize_user(strtok($email,'@'),true)?:'applicant';$login=$base;$i=1;while(username_exists($login))$login=$base.$i++;$uid=wp_create_user($login,$password,$email);if(is_wp_error($uid))return$uid;$user=new WP_User($uid);$user->set_role('nvconsult_applicant');wp_update_user(['ID'=>$uid,'display_name'=>$name,'first_name'=>$name]);return new WP_REST_Response(['user_id'=>$uid,'message'=>__('Account created. Please sign in to continue.','nvconsult-core')],201);}
 public static function claim(WP_REST_Request$r){$id=absint($r['application_id']);$token=sanitize_text_field((string)$r['tracking_token']);if(!$id||get_post_type($id)!=='nv_application'||$token==='')return new WP_Error('invalid_claim',__('Invalid application claim.','nvconsult-core'),['status'=>400]);$owner=absint(get_post_meta($id,'_nvconsult_user_id',true));if($owner&&$owner!==get_current_user_id())return new WP_Error('already_claimed',__('This application is already linked to another account.','nvconsult-core'),['status'=>409]);$hash=(string)get_post_meta($id,'_nvconsult_tracking_hash',true);if(!$hash||!wp_check_password($token,$hash))return new WP_Error('invalid_token',__('The tracking token is invalid.','nvconsult-core'),['status'=>403]);$app_email=strtolower(sanitize_email((string)get_post_meta($id,'_nvconsult_email',true)));$user=wp_get_current_user();if(!$app_email||strtolower($user->user_email)!==$app_email)return new WP_Error('email_mismatch',__('Sign in using the same email address used for the application.','nvconsult-core'),['status'=>403]);update_post_meta($id,'_nvconsult_user_id',$user->ID);delete_post_meta($id,'_nvconsult_tracking_hash');add_post_meta($id,'_nvconsult_history',['time'=>current_time('mysql'),'type'=>'ownership','message'=>__('Application linked to applicant account.','nvconsult-core'),'user'=>$user->display_name,'user_id'=>$user->ID]);return new WP_REST_Response(['application_id'=>$id,'claimed'=>true],200);}
}
